INSERT INTO `about_page_settings` (`id`, `discover_section`, `chairman_message_section`, `board_of_directors_section`, `our_story_section`, `direction_purpose_section`, `strategic_pillars_section`, `people_values_section`, `efficiency_certificates_section`, `factory_section`, `carbon_free_future_section`, `updated_at`) VALUES (1, '{"cards":[{"title":"500+ MW7","subtitle":"Solar & Clean Tech"},{"title":"50+","subtitle":"Countries Exported"},{"title":"99.8%","subtitle":"Uptime Reliability"},{"title":"24/9","subtitle":"Smart Grid Monitoring"}],"description":"Pioneering utility scale solar power farms, offshore wind generation, zero-downtime battery storage, and advanced diagnostic medical technology globally.","small_title":"Discover Solvex Global","button_1_text":"Request System Audit","button_2_text":"Explore Solutions","big_title_1st_line":"Engineering","big_title_second_line":"Infrastructure for Humanity","big_title_1st_line_style":"Sustainable","big_title_1st_line_style_color":"#10b981"}', '{"name":"Tariqul Islam","image":"http://localhost:5000/uploads/images__1_-1789228396809-364948741.jpg","small_title":"Chairman\'s Address","name_on_image":"Tariqul Islam","big_size_quote":"Our mission is to empower developing and modern economies with uninterrupted renewable power and life-saving healthcare innovation.","company_on_image":"Solvex Global Ltd.","small_size_quote":"Energy independence and reliable medical diagnostics are basic human rights.","normal_size_quote":"Through strategic engineering alliances and Tier-1 certified equipment, Solvex Global is building the backbone of tomorrow\'s sustainable infrastructure.","pill_text_on_image":"FOUNDER & CHAIRMAN","designation_on_image":"Chairman of the Board","bottom_right_pill_text":"Global Excellence Award 2026","designation_and_company":"Chairman & Founder, Solvex Global Ltd"}', '{"big_title":"Board of Directors","description":"Distinguished industry pioneers and corporate leaders directing Solvex Global\'s long-term sustainability charter.","small_title":"OUR GOVERNANCE"}', '{"image":"https://backend.solvexgloballtd.com/storage/homepage/sliders/solar_panel_hero.png","roadmap":[{"title":"Inception & Commercial Solar EPC","duration":"2011 – 2016","description":"Established as a specialist engineering firm focusing on high-quality commercial rooftop solar installations with German inverter technology.","duration_color":"#10b981"},{"title":"Industrial Scale Expansion & 50+ MW Milestone","duration":"2017 – 2021","description":"Expanded into heavy industrial textile, ceramics, and export manufacturing sectors, crossing 50 MWp of net-metered rooftop installations.","duration_color":"#0ea5e9"},{"title":"BESS Integration & Utility-Scale Leadership","duration":"2022 – PRESENT","description":"Pioneered containerized LiFePO4 battery energy storage, floating solar arrays, and high-voltage grid substations exceeding 120+ MWp capacity.","duration_color":"#eab308"}],"tag_text":"15 YEARS OF INNOVATION","big_title":"Pioneering Clean Power","tag_color":"#10b981","card_title":"Unbroken Record of Bankability & Safety","description":"Over fifteen years, Solvex Global evolved from installing high-efficiency commercial rooftop arrays into a full-scale renewable EPC enterprise delivering multi-megawatt industrial solar parks and containerized BESS infrastructure.","small_title":"Our Journey & Legacy","big_style_title":"Since Inception","card_description":"Zero structural failures and over 1.2 billion kilowatt-hours generated safely across heavy industrial environments.","big_style_title_color":"#10b981"}', '{"cards":[{"title":"Our Mission","description":"To deliver highest-yield turnkey solar and battery storage solutions that liberate industrial enterprises from volatile fossil energy costs and drive global decarbonization.","bullet_points":["jjj","Maximum return on investment through optimized kilowatt-hour yields","Unconditional commitment to occupational health and structural safety"]},{"title":"Our Vision","description":"To be South Asia\'s most trusted clean energy infrastructure partner, powering a 100% resilient, electrified, and carbon-neutral industrial ecosystem.","bullet_points":["500+ MWp clean energy capacity target by 2030","Advancing next-generation energy storage & microgrid intelligence","Fostering local high-technology engineering talent in green power"]}],"big_title":"Guided by Principles","description":"Our purpose is built upon long-term environmental stewardship and human-centric healthcare innovation.","small_title":"Direction & Purpose"}', '{"cards":[{"title":"Engineering Rigor","description":"Advanced 3D shading simulations, STAAD.Pro finite element modeling, and strict IEC 62446 commissioning standards."},{"title":"Tier-1 Supply Bankability","description":"Direct partnerships with BloombergNEF Tier-1 solar panel and CATL/EVE battery cell manufacturers."},{"title":"Lifecycle Asset Care","description":"Proactive AI-powered SCADA telemetry, automated drone thermography, and 24/7 technical field support."},{"title":"Decarbonization Impact","description":"Empowering our industrial partners to fulfill Scope 1 & 2 carbon reduction goals and international ESG export audits."}],"big_title":"Four Strategic Pillars","description":"Every solar module placed and every high-voltage transformer energized is grounded in our four core operational pillars.","small_title":"⚡ FOUNDATIONAL PRINCIPLES"}', '{"cards":[{"title":"Safety Above All","description":"Zero-harm workplace philosophy with rigorous adherence to OSHA and high-voltage electrical safety protocols.","colored_number":"01"},{"title":"Technical Precision","description":"No cutting corners on cabling, balance of system, or structural anchors—built to last 30+ years.","colored_number":"02"},{"title":"Customer Centricity","description":"Transparent communication, reliable generation forecasting, and lifelong partnership with factory owners.","colored_number":"03"},{"title":"Continuous Innovation","description":"Embracing next-gen TOPCon cells, smart microgrids, and AI digital twin monitoring to maximize ROI.","colored_number":"04"}],"big_title":"Our Core Values","description":"Behind every successful megawatt-scale project is our passionate team of certified electrical engineers, safety officers, and clean energy innovators.","small_title":"🍃 CULTURE & VALUES"}', '{"cards":[{"label":"QUALITY MANAGEMENT","title":"ISO 9001:2015 Certified","description":"Certified quality management systems covering design, procurement, EPC execution, and post-commissioning maintenance."},{"label":"ENVIRONMENTAL HEALTH","title":"ISO 14001:2015 & ISO 45001","description":"Comprehensive occupational health, environmental protection, and zero-accident site safety frameworks."},{"label":"SOLAR & BESS STANDARDS","title":"IEC 62446 & IEC 62619 Compliance","description":"Strict adherence to international electrical commission standards for solar PV testing and industrial lithium battery storage safety."}],"big_title":"Certified International Quality","description":"Our operations, safety management, and engineering deliverables are certified under rigorous international standards organizations.","small_title":"🏅 ACCREDITATIONS & STANDARDS","certificates":[{"id":"cert-1","pdf":"","name":"CE","image":"https://images.unsplash.com/photo-1607604276583-eef5d076aa5f?w=800&auto=format&fit=crop&q=80","issuer":"European Conformity Certification"},{"id":"cert-2","pdf":"","name":"UPS-CE","image":"https://images.unsplash.com/photo-1589829545856-d10d557cf95f?w=800&auto=format&fit=crop&q=80","issuer":"Uninterruptible Power Supply CE Compliance"},{"id":"cert-3","pdf":"","name":"IEC","image":"https://images.unsplash.com/photo-1554224155-8d04cb21cd6c?w=800&auto=format&fit=crop&q=80","issuer":"Shenzhen Anbotek Compliance Laboratory"},{"id":"cert-4","pdf":"","name":"ROHS","image":"https://images.unsplash.com/photo-1450133064473-71024230f91b?w=800&auto=format&fit=crop&q=80","issuer":"Restriction of Hazardous Substances Compliance"},{"id":"cert-5","pdf":"","name":"ISO 9001:2015","image":"https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?w=800&auto=format&fit=crop&q=80","issuer":"Quality Management System Accreditation"},{"id":"cert-6","pdf":"","name":"IEC 62446","image":"https://images.unsplash.com/photo-1497366216548-37526070297c?w=800&auto=format&fit=crop&q=80","issuer":"Grid-Connected PV Systems Documentation & Verification"}]}', '{"stats":[{"label":"Facility Footprint","value":"280,000 sq ft"},{"label":"Annual Capacity","value":"500+ MWp"},{"label":"Automated SMT Lines","value":"100% Robotics"},{"label":"Quality Burn-in Testing","value":"48 Hours"}],"images":[{"url":"https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?w=1000&auto=format&fit=crop&q=80","title":"Automated Robotics Assembly","description":"Sub-millimeter precision surface-mount technology."},{"url":"https://images.unsplash.com/photo-1581092335397-9583fe92d232?w=1000&auto=format&fit=crop&q=80","title":"High-Voltage Testing & QC Lab","description":"Rigorous electrical dielectric and thermal stress validation."},{"url":"https://images.unsplash.com/photo-1581092160607-ee22621dd758?w=1000&auto=format&fit=crop&q=80","title":"Cleanroom Production Facility","description":"ISO Class 10,000 certified micro-climate assembly."}],"big_title":"State-of-the-Art Factory & High-Tech Facilities","description":"Engineered with world-class German automated machinery, ISO Class 10,000 cleanroom environments, and 48-hour burn-in testing chambers to guarantee zero-defect solar and BESS manufacturing.","small_title":"MANUFACTURING EXCELLENCE"}', '{}', '2026-09-20 03:34:34');

