INSERT INTO `homepage_settings` (`id`, `slider_section`, `service_cards`, `running_text`, `about_section`, `counter_section`, `why_choose_us_section`, `working_process_section`, `solutions_section`, `faq_section`, `testimonial_section`, `section_visibility`, `updated_at`, `services_header`, `board_of_directors_section`, `projects_section`, `sister_concern_section`, `products_section`, `news_and_blog_section`) VALUES (1, '[{"id":"slide-1","image_1":"https://image.solvexgloballtd.com/uploads/1789288549708-653475725.webp","image_2":"https://image.solvexgloballtd.com/uploads/1789288544689-739326945.webp","image_3":"https://image.solvexgloballtd.com/uploads/1789288545150-707423116.webp","big_title":"Powering Tomorrow with Intelligent Solar Energy","button_url":"/services","card_badge":"$ ↓","card_title":"Cost Savings","button_text":"Explore Our Solutions","description":"Pioneering utility-scale PV, smart BESS energy storage, and industrial-grade high-frequency power solutions across Bangladesh and global markets.","small_title":"GLOBAL ENERGY & SOLAR INFRASTRUCTURE","card_description":"Over time, solar energy can significantly lower electricity bills and allow selling power back to the grid.","button_secondary_url":"#calculator","button_secondary_text":"Audit Sizing Calculator"},{"id":"slide-2","image_1":"https://image.solvexgloballtd.com/uploads/1789288546061-705316393.webp","image_2":"https://image.solvexgloballtd.com/uploads/1789288546687-947690242.webp","image_3":"https://image.solvexgloballtd.com/uploads/1789288547922-892866926.webp","big_title":"Next-Gen Commercial & Industrial Hybrid Inverters","button_url":"/products","card_badge":"99.8% Uptime","card_title":"Zero Transfer Glitch","button_text":"View Products","description":"Engineered with dual MPPTs, IP66 rugged outdoor casing, and 9-unit parallel scalability for 100% resilient off-grid and on-grid continuity.","small_title":"SMART ENERGY STORAGE SYSTEMS","card_description":"Pure sine wave power continuity engineered for uninterrupted industrial manufacturing and medical theaters.","button_secondary_url":"/contact","button_secondary_text":"Request a Quote"}]', '[{"id":"sc-1","icon":"SunMedium","title":"Utility-Scale Solar PV Plants","description":"Turnkey EPC development from high-irradiance engineering to grid synchronization and 25-year performance monitoring."},{"id":"sc-2","icon":"BatteryCharging","title":"C&I BESS Battery Storage","description":"High-capacity lithium iron phosphate (LiFePO4) storage for peak shaving, demand management, and continuous factory backup."},{"id":"sc-3","icon":"Wind","title":"Wind & Hybrid Microgrids","description":"Clean hybrid architectures combining solar, wind, and intelligent diesel generator synchronization."},{"id":"sc-4","icon":"Activity","title":"Healthcare Critical Power","description":"Zero-transfer-time medical-grade pure sine wave UPS systems for hospital ICUs, imaging centers, and emergency hubs."}]', '[{"id":"rt-1","title":"100+ MW Utility Solar Deployed"},{"id":"rt-2","title":"IP66 Certified Waterproof Engineering"},{"id":"rt-3","title":"Tier-1 Hybrid Inverters & Lithium Storage"},{"id":"rt-4","title":"24/7 Remote Telemetry & BMS Telematics"},{"id":"rt-5","title":"ISO 9001 & CE Certified Quality"}]', '{"tag_icon":"Sparkles","tag_text":"20+ YEARS OF INDUSTRIAL ENGINEERING","big_title":"Empowering Industries with Clean, Uninterrupted Energy","button_url":"/about","mini_title":"Architecting Sustainable Power Solutions","video_link":"https://www.youtube.com/watch?v=dQw4w9WgXcQ","button_text":"Discover Our Full Story","description":"Solvex Global Ltd stands at the vanguard of renewable energy and critical power infrastructure. We bridge cutting-edge international solar technologies with local industrial needs, delivering turnkey EPC projects, high-frequency inverters, and battery systems that lower carbon footprints while maximizing operational profitability.","person_name":"Engr. M. A. Rahman","person_image":"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=400","bullet_points":["Tier-1 manufacturing partnerships with international solar leaders","Dedicated R&D engineering division for tropical climate optimization","Guaranteed 25-year performance warranties with full local RMA support","Smart IoT telemetry and cloud telemetry integration on all deployments"],"telemetry_text":"99.8% Grid Uptime Rating","experience_text":"30+ Years Global Legacy","telemetry_label":"LIVE TELEMETRY","experience_image":"/about_engineers.png","experience_label":"ESTABLISHED 1996","person_designation":"Chief Executive Officer & Founder"}', '[{"id":"cnt-1","counter":"150+","description":"MW Total Solar Capacity Installed"},{"id":"cnt-2","counter":"99.8%","description":"System Uptime & Grid Reliability"},{"id":"cnt-3","counter":"450+","description":"Commercial & Industrial Projects"}]', '{"tag":"THE SOLVEX ADVANTAGE","title":"Engineered for Uncompromising Performance","metrics":[{"id":"m-1","label":"Energy Cost Reduction","percentage":92},{"id":"m-2","label":"Hardware Efficiency Rate","percentage":98},{"id":"m-3","label":"Client Retention & SLA Delivery","percentage":99}],"description":"Every megawatt we engineer is backed by rigorous environmental stress testing, high-grade Tier-1 bill of materials, and guaranteed service level agreements."}', '{"tag":"STREAMLINED EXECUTION","steps":[{"id":"step-1","title":"Energy Audit & Load Profiling","description":"High-resolution telemetry assessment of your daytime and nighttime industrial consumption curve.","step_number":"01"},{"id":"step-2","title":"Simulation & Electrical Design","description":"CAD single-line diagrams, string sizing, MPPT yield modeling, and shading analysis.","step_number":"02"},{"id":"step-3","title":"Certified Turnkey EPC Installation","description":"Rapid deployment adhering to BNBC, IEC, and global safety standards with zero factory downtime.","step_number":"03"},{"id":"step-4","title":"Grid Sync & Lifetime RMA Care","description":"Formal net-metering approval, cloud SCADA setup, and dedicated on-site maintenance teams.","step_number":"04"}],"title":"Our 4-Step Engineering Lifecycle","description":"From solar irradiation feasibility studies to lifetime telemetry monitoring, we ensure zero operational bottlenecks."}', '{"big_title":"Tailored Clean Energy Solutions","description":"Explore our specialized divisions built to address every scale of energy demand.","small_title":"INNOVATIVE ARCHITECTURES"}', '[{"id":"faq-1","answer":"Under Bangladesh net metering guidelines, excess electricity generated during peak sunlight is exported back to the national grid (DPDC, DESCO, REB, etc.) and credited against your monthly billing, dramatically reducing operational electricity expenses.","question":"How does net metering work with Solvex industrial solar installations?"},{"id":"faq-2","answer":"Our Solvex hybrid inverters come standard with 5 to 10-year manufacturer replacement warranties, with design lifespans exceeding 15 to 20 years when maintained under standard operating temperatures.","question":"What is the lifespan and warranty coverage of your hybrid inverters?"},{"id":"faq-3","answer":"Yes! Our XA-series hybrid inverters feature advanced battery-independent PV mode, allowing your facility to run daytime loads directly from solar generation even during utility blackout conditions.","question":"Can Solvex systems operate without batteries during daytime grid outages?"},{"id":"faq-4","answer":"Most commercial and industrial rooftop solar systems achieve full capital expenditure payback within 3.5 to 5 years, providing free clean electricity for the remaining 20+ years of panel operational life.","question":"What financing and ROI payback periods can commercial clients expect?"}]', '[{"id":"test-1","name":"Ahmed Kabir","role":"Director of Plant Operations","avatar":"https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=200","rating":5,"company":"Apex Spinning & Weaving Mills","content":"Solvex deployed our 1.2MW rooftop solar array with absolute precision. Our daytime diesel generator run-time dropped by 75%, and the ROI has exceeded all initial projections."},{"id":"test-2","name":"Engr. Farhana Chowdhury","role":"Chief Medical Systems Engineer","avatar":"https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?w=200","rating":5,"company":"CareMed Specialist Hospital","content":"The pure sine wave medical UPS and BESS setup engineered by Solvex gives our operating theaters 100% reliable power continuity with zero transfer glitch."}]', '{"news_blog":true,"faq_section":true,"hero_slider":true,"feature_grid":true,"team_members":true,"testimonials":true,"why_choose_us":true,"about_overview":true,"roi_calculator":true,"partner_marquee":true,"project_gallery":true,"working_process":true,"divisions_section":true,"products_carousel":true,"solutions_showcase":true}', '2026-09-16 21:50:39', '{"tag":"OUR CORE SERVICESy","badge":"OUR CORE SERVICESy","title":"High-Performance Solar Solutions","subtitle":"Engineered for Maximum Industrial & Commercial Efficiency","big_title":"High-Performance Solar Solutions","description":"Delivering tier-1 solar photovoltaic panels, smart energy storage systems, and comprehensive microgrid solutions.","small_title":"OUR CORE SERVICESy"}', '{"badge":"OUR GOVERNANCE & LEADERSHIP","title":"Board of Directors","subtitle":"Executive Leadership","description":"Steered by seasoned clean tech visionaries, utility power system engineers, and sustainable finance experts.","translations":{"bn":{"badge":"আমাদের পরিচালনা ও নেতৃত্ব","title":"পরিচালনা পর্ষদ","subtitle":"নির্বাহী নেতৃত্ব","description":"অভিজ্ঞ ক্লিন টেক দূরদর্শী, ইউটিলিটি পাওয়ার সিস্টেম প্রকৌশলী এবং টেকসই অর্থ বিশেষজ্ঞদের দ্বারা পরিচালিত।"}}}', NULL, NULL, NULL, NULL);

