INSERT INTO `projects` (`id`, `slug`, `project_category_id`, `label`, `big_title`, `description_cards`, `details_card`, `faq_icon`, `faq_title`, `faq_description`, `faq_questions`, `status`, `order_index`, `translations`, `created_at`, `updated_at`) VALUES (1, '5-2-mwp-commercial-rooftop-solar-epc', 1, 'Turnkey Industrial EPC', '5.2 MWp Commercial Rooftop Solar EPC Deployment', '[{"title":"5.2 MWp","subtitle":"System Capacity"},{"title":"6.8 GWh","subtitle":"Annual Yield"},{"title":"4,200 Tons","subtitle":"CO2 Offset"},{"title":"3.8 Years","subtitle":"Capital Payback"}]', '[{"image":"https://images.unsplash.com/photo-1508873696983-2df5293cb395?w=800&auto=format&fit=crop&q=80","label":"Milestone 01","title":"Structural Aerodynamic Modeling & Ballast Integration","image_left":false,"label_color":"#10B981","bullet_points":[{"text":"Zero roof penetration with marine-grade AL6005-T5 anodized aluminum clamping.","icon_color":"#10B981"},{"text":"Certified wind-tunnel resilience up to 180 km/h wind shear ratings.","icon_color":"#10B981"}],"description_1":"Engineered specifically for heavy industrial corrugated tin and standing seam roofs, featuring non-penetrating clamps tested to 180 km/h wind speeds.","description_2":"Full 3D LiDAR point-cloud scans and shadow analysis ensured maximum annual kilowatt-hour density across the 280,000 sq ft factory footprint."},{"image":"https://images.unsplash.com/photo-1509391365360-2e959784a276?w=800&auto=format&fit=crop&q=80","label":"Milestone 02","title":"Tier-1 TOPCon Bifacial Modules & String Inverter Architecture","image_left":true,"label_color":"#06B6D4","bullet_points":[{"text":"N-Type TOPCon bifacial modules achieving up to 22.8% conversion efficiency.","icon_color":"#06B6D4"},{"text":"Multi-MPPT string architecture with rapid shutdown and SCADA telemetry.","icon_color":"#06B6D4"}],"description_1":"Deployment of high-yield N-Type TOPCon bifacial modules coupled with multi-MPPT smart string inverters for real-time string-level yield optimization.","description_2":"Euro efficiency rating of 99.0% with automated AI-assisted arc fault circuit interruption (AFCI) protecting facility assets 24/7."}]', NULL, 'Project FAQs', 'Technical inquiries regarding the 5.2 MWp industrial rooftop project.', '[{"answer":"We deploy precision-engineered aluminum standing-seam clamps with EPDM rubber dampening that grip the seams without puncturing the roof sheet, preserving 100% of factory waterproofing warranties.","question":"How does the non-penetrating clamping protect the factory roof?"}]', 'published', 1, NULL, '2026-09-16 19:48:36', '2026-09-16 19:48:36');
INSERT INTO `projects` (`id`, `slug`, `project_category_id`, `label`, `big_title`, `description_cards`, `details_card`, `faq_icon`, `faq_title`, `faq_description`, `faq_questions`, `status`, `order_index`, `translations`, `created_at`, `updated_at`) VALUES (1, '10-mwh-containerized-industrial-bess', 1, 'Utility Microgrid', '10 MWh Containerized Industrial BESS Peak Shaving Hub', '[{"title":"10.4 MWh","subtitle":"Energy Storage"},{"title":"5.0 MW","subtitle":"Inverter Rating"},{"title":"92.5%","subtitle":"Round-Trip Eff"},{"title":"100%","subtitle":"Zero Outage"}]', '[{"image":"https://images.unsplash.com/photo-1513836279014-a89f7a76ae86?w=800&auto=format&fit=crop&q=80","label":"Milestone 01","title":"Liquid-Cooled Battery Enclosures & Fire Safety","image_left":false,"label_color":"#06B6D4","bullet_points":[{"text":"Liquid cooling maintains cell temperature variance below 2.0°C.","icon_color":"#06B6D4"},{"text":"NFPA 855 and UL 9540A safety compliance certification.","icon_color":"#06B6D4"}],"description_1":"Designed for a heavy manufacturing zone suffering from frequent grid voltage sags and rolling brownouts.","description_2":"Utilizes advanced LFP chemistry with comprehensive cell-level monitoring and integrated clean-agent fire suppression."}]', NULL, 'BESS Project Details', 'Technical questions regarding the 10 MWh battery installation.', '[{"answer":"The BESS system engages in under 15 milliseconds, ensuring continuous operation of sensitive robotics and computerized knitting lines.","question":"How fast is the transfer time during a power cut?"}]', 'published', 1, NULL, '2026-09-16 19:48:36', '2026-09-16 19:48:36');
INSERT INTO `projects` (`id`, `slug`, `project_category_id`, `label`, `big_title`, `description_cards`, `details_card`, `faq_icon`, `faq_title`, `faq_description`, `faq_questions`, `status`, `order_index`, `translations`, `created_at`, `updated_at`) VALUES (1, '8-4-mwp-composite-textile-solar', 1, 'LEED Platinum Certified', '8.4 MWp Composite Textile Mills Rooftop PV Plant', '[{"title":"8.4 MWp","subtitle":"Installed Capacity"},{"title":"11.2 GWh","subtitle":"Annual Generation"},{"title":"320,000 sq ft","subtitle":"Roof Coverage"},{"title":"7,100 Tons","subtitle":"CO2 Avoided"}]', '[{"image":"https://images.unsplash.com/photo-1613665813446-82a78c468a1d?w=800&auto=format&fit=crop&q=80","label":"Milestone 01","title":"Textile Factory Roof Retrofit & Structural Reinforcement","image_left":false,"label_color":"#10B981","bullet_points":[{"text":"Supplies over 38% of total annual manufacturing energy.","icon_color":"#10B981"},{"text":"Achieved LEED Platinum zero-carbon factory certification.","icon_color":"#10B981"}],"description_1":"One of the largest self-consumption rooftop solar installations in South Asia, spread across five interconnected spinning sheds.","description_2":"Enables the textile conglomerate to meet strict European carbon compliance and global buyer ESG mandates."}]', NULL, 'Textile Solar Case Study', 'Details on industrial textile mill solar installations.', '[{"answer":"Zero manufacturing downtime occurred. All lifting and mechanical mounting were coordinated during scheduled weekend maintenance shifts.","question":"Did factory operations stop during solar installation?"}]', 'published', 1, NULL, '2026-09-16 19:48:36', '2026-09-16 19:48:36');
INSERT INTO `projects` (`id`, `slug`, `project_category_id`, `label`, `big_title`, `description_cards`, `details_card`, `faq_icon`, `faq_title`, `faq_description`, `faq_questions`, `status`, `order_index`, `translations`, `created_at`, `updated_at`) VALUES (1, '25-mwp-utility-scale-solar-farm', 1, '132kV Substation', '25 MWp Utility-Scale Ground-Mounted Solar Farm', '[{"title":"25.0 MWp","subtitle":"Nominal Power"},{"title":"38.5 GWh","subtitle":"Annual Yield"},{"title":"1-Axis","subtitle":"Smart Trackers"},{"title":"132kV","subtitle":"Grid Substation"}]', '[{"image":"https://images.unsplash.com/photo-1497435334941-8c899ee9e8e9?w=800&auto=format&fit=crop&q=80","label":"Milestone 01","title":"Astronomical Single-Axis Tracking on 85 Acres","image_left":false,"label_color":"#F59E0B","bullet_points":[{"text":"Over 42,000 N-Type bifacial solar panels installed.","icon_color":"#F59E0B"},{"text":"Automated weather station stowing against monsoon gales.","icon_color":"#F59E0B"}],"description_1":"Utility power plant feeding clean electricity directly into the national power grid through a dedicated 132kV switchyard.","description_2":"Equipped with AI terrain-adaptive algorithms to optimize generation on undulating land."}]', NULL, 'Utility Project Questions', 'Grid connection and technical specifications.', '[{"answer":"The plant is engineered for greater than 99.2% technical availability, monitored 24/7 by central SCADA.","question":"What is the expected plant availability rate?"}]', 'published', 1, NULL, '2026-09-16 19:48:36', '2026-09-16 19:48:36');
INSERT INTO `projects` (`id`, `slug`, `project_category_id`, `label`, `big_title`, `description_cards`, `details_card`, `faq_icon`, `faq_title`, `faq_description`, `faq_questions`, `status`, `order_index`, `translations`, `created_at`, `updated_at`) VALUES (1, '3-6-mwp-pharma-cleanroom-solar', 1, 'Pharma Clean-Room', '3.6 MWp Pharmaceutical Manufacturing Clean Solar Array', '[{"title":"3.6 MWp","subtitle":"Peak Power"},{"title":"4.9 GWh","subtitle":"Annual Generation"},{"title":"Zero Dust","subtitle":"Sterile Standard"},{"title":"99.8%","subtitle":"Power Quality"}]', '[{"image":"https://images.unsplash.com/photo-1548337138-e87d889cc369?w=800&auto=format&fit=crop&q=80","label":"Milestone 01","title":"Cleanroom Safe Installation & Power Quality Harmonization","image_left":false,"label_color":"#10B981","bullet_points":[{"text":"Active harmonic filtering maintaining THD below 2.5%.","icon_color":"#10B981"},{"text":"Full WHO-GMP environmental compliance during execution.","icon_color":"#10B981"}],"description_1":"Engineered above sterile pharmaceutical formulation labs with active active harmonic filters ensuring clean power for precision lab instruments.","description_2":"Non-vibrational installation techniques ensured zero particulate contamination inside cleanrooms during mounting."}]', NULL, 'Pharma Solar FAQ', 'High-spec power quality and cleanroom safety.', '[{"answer":"No, our multi-level power conditioning and active filters provide cleaner sine-wave power than the incoming utility grid.","question":"Does solar power affect sensitive pharmaceutical machinery?"}]', 'published', 1, NULL, '2026-09-16 19:48:36', '2026-09-16 19:48:36');
INSERT INTO `projects` (`id`, `slug`, `project_category_id`, `label`, `big_title`, `description_cards`, `details_card`, `faq_icon`, `faq_title`, `faq_description`, `faq_questions`, `status`, `order_index`, `translations`, `created_at`, `updated_at`) VALUES (1, '2-2-mwp-floating-solar-reservoir', 1, 'Water Reservoir FPV', '2.2 MWp Floating Solar PV Array on Industrial Reservoir', '[{"title":"2.2 MWp","subtitle":"Floating Solar"},{"title":"3.1 GWh","subtitle":"Annual Energy"},{"title":"35%","subtitle":"Evap Reduction"},{"title":"12%","subtitle":"Thermal Gain"}]', '[{"image":"https://images.unsplash.com/photo-1521618755572-156ae0cdd74d?w=800&auto=format&fit=crop&q=80","label":"Milestone 01","title":"Aquatic Pontoon Deployment on Raw Water Reservoir","image_left":false,"label_color":"#06B6D4","bullet_points":[{"text":"Conserved 18 million gallons of industrial water annually.","icon_color":"#06B6D4"},{"text":"Food-grade HDPE floats prevent water contamination.","icon_color":"#06B6D4"}],"description_1":"Built upon a textile factory\'s 12-acre raw water lake, conserving valuable expansion land while cooling the solar cells naturally.","description_2":"Anchored with corrosion-proof mooring cables accommodating a 5-meter seasonal water level variation."}]', NULL, 'Floating Solar FAQ', 'Aquatic stability and environmental benefits.', '[{"answer":"It actually improves water quality by shading the pond from UV sunlight, preventing algae blooms that clog treatment filters.","question":"Does floating solar affect water quality for factory processing?"}]', 'published', 1, NULL, '2026-09-16 19:48:36', '2026-09-16 19:48:36');
INSERT INTO `projects` (`id`, `slug`, `project_category_id`, `label`, `big_title`, `description_cards`, `details_card`, `faq_icon`, `faq_title`, `faq_description`, `faq_questions`, `status`, `order_index`, `translations`, `created_at`, `updated_at`) VALUES (1, '4-5-mwp-steel-mill-solar-diesel-hybrid', 1, 'Steel Mill Microgrid', '4.5 MWp Steel Re-Rolling Mill Solar-Genset Microgrid', '[{"title":"4.5 MWp","subtitle":"PV Hybrid"},{"title":"1.8M Liters","subtitle":"Diesel Saved"},{"title":"Zero","subtitle":"Reverse Feed"},{"title":"100 ms","subtitle":"Response Speed"}]', '[{"image":"https://images.unsplash.com/photo-1473341304170-971dccb5ac1e?w=800&auto=format&fit=crop&q=80","label":"Milestone 01","title":"Heavy Inductive Load Management & Fast Solar Dispatch","image_left":false,"label_color":"#F59E0B","bullet_points":[{"text":"Advanced fast-response power curtailment prevents generator reverse-power trips.","icon_color":"#F59E0B"},{"text":"Real-time reactive power compensation boosts plant power factor.","icon_color":"#F59E0B"}],"description_1":"Steel mills experience severe load swings from electric arc furnaces and rolling stands. Our dynamic controller manages solar output in real-time.","description_2":"Synchronized with 4 x 2,000 kVA diesel generators to slash monthly fuel costs by over 40%."}]', NULL, 'Steel Mill Microgrid FAQ', 'Heavy industry power stabilization.', '[{"answer":"Yes, the hybrid controller works alongside generators and fast inverters to absorb voltage dips seamlessly.","question":"Can solar handle instantaneous motor starting surges?"}]', 'published', 1, NULL, '2026-09-16 19:48:36', '2026-09-16 19:48:36');
INSERT INTO `projects` (`id`, `slug`, `project_category_id`, `label`, `big_title`, `description_cards`, `details_card`, `faq_icon`, `faq_title`, `faq_description`, `faq_questions`, `status`, `order_index`, `translations`, `created_at`, `updated_at`) VALUES (1, '1-8-mwp-corporate-solar-carport', 1, 'Solar Carport & EV', '1.8 MWp Corporate Headquarters Solar Carport & EV Hub', '[{"title":"1.8 MWp","subtitle":"Canopy Array"},{"title":"650","subtitle":"Shaded Bays"},{"title":"30","subtitle":"Fast Chargers"},{"title":"2.4 GWh","subtitle":"Annual Solar"}]', '[{"image":"https://images.unsplash.com/photo-1545209568-98e3b3318182?w=800&auto=format&fit=crop&q=80","label":"Milestone 01","title":"Architectural Steel Canopy with Integrated EV Fleet Chargers","image_left":false,"label_color":"#10B981","bullet_points":[{"text":"100% waterproof sealed canopy with internal rainwater downspouts.","icon_color":"#10B981"},{"text":"Smart RFID-enabled employee EV charging management software.","icon_color":"#10B981"}],"description_1":"Transforms open-air executive parking into an energy-generating landmark for a multinational technology campus.","description_2":"Includes 30 high-speed EV charging stations powered by 100% on-site generated solar electricity."}]', NULL, 'Solar Carport FAQ', 'Corporate e-mobility and architectural design.', '[{"answer":"All structural columns are anchored into reinforced concrete pile foundations certified to resist 170 km/h wind shear.","question":"Are solar carports resistant to high monsoon winds?"}]', 'published', 1, NULL, '2026-09-16 19:48:36', '2026-09-16 19:48:36');
INSERT INTO `projects` (`id`, `slug`, `project_category_id`, `label`, `big_title`, `description_cards`, `details_card`, `faq_icon`, `faq_title`, `faq_description`, `faq_questions`, `status`, `order_index`, `translations`, `created_at`, `updated_at`) VALUES (1, '6-0-mwp-jute-packaging-solar', 1, 'Agro-Industrial Solar', '6.0 MWp Jute & Packaging Processing Facility Solar Array', '[{"title":"6.0 MWp","subtitle":"Total Output"},{"title":"8.1 GWh","subtitle":"Annual Yield"},{"title":"4,900 Tons","subtitle":"Emissions Avoided"},{"title":"4.1 Years","subtitle":"Payback Period"}]', '[{"image":"https://images.unsplash.com/photo-1559302504-64aae6ca6b6d?w=800&auto=format&fit=crop&q=80","label":"Milestone 01","title":"Long-Span Roof Structural Engineering for Agro-Industry","image_left":false,"label_color":"#10B981","bullet_points":[{"text":"High-yield N-Type TOPCon panels for humid sub-tropical conditions.","icon_color":"#10B981"},{"text":"Automated dry-cleaning system reduces water consumption to zero.","icon_color":"#10B981"}],"description_1":"Equipped with automated anti-soiling drone inspections and string-level fault monitoring across four large packaging mills.","description_2":"Generates massive operational cost savings that hedge the facility against rising grid utility tariffs."}]', NULL, 'Agro-Industrial Solar FAQ', 'Jute and packaging facility solar benefits.', '[{"answer":"Robotic dry-cleaning runs every morning before sunrise, keeping module glass spotless without manual water spraying.","question":"How does the system handle fiber dust accumulation?"}]', 'published', 1, NULL, '2026-09-16 19:48:36', '2026-09-16 19:48:36');
INSERT INTO `projects` (`id`, `slug`, `project_category_id`, `label`, `big_title`, `description_cards`, `details_card`, `faq_icon`, `faq_title`, `faq_description`, `faq_questions`, `status`, `order_index`, `translations`, `created_at`, `updated_at`) VALUES (1, '15-mwp-cement-clinker-renewable-station', 1, 'Heavy Industry Microgrid', '15 MWp Cement Clinker Facility Renewable Power Station', '[{"title":"15.0 MWp","subtitle":"PV System"},{"title":"21.6 GWh","subtitle":"Clean Energy"},{"title":"14,200 Tons","subtitle":"CO2 Cut"},{"title":"33kV","subtitle":"Dedicated Feeder"}]', '[{"image":"https://images.unsplash.com/photo-1466611653911-95081537e5b7?w=800&auto=format&fit=crop&q=80","label":"Milestone 01","title":"High-Voltage Interconnection & Heavy Industrial Offset","image_left":false,"label_color":"#F59E0B","bullet_points":[{"text":"High-spec IP66 inverters engineered for dusty cement environments.","icon_color":"#F59E0B"},{"text":"Full SCADA remote telemetry dispatch integrated with plant DCS.","icon_color":"#F59E0B"}],"description_1":"Supplying green energy directly to high-torque ball mills and clinker crushers via a dedicated 33kV internal substation.","description_2":"Significantly reduces the carbon intensity of cement manufacturing to comply with green building standards."}]', NULL, 'Cement Industry Solar FAQ', 'High-dust heavy industrial clean energy.', '[{"answer":"All inverters and junction boxes feature IP66 hermetic sealing with pressurized cooling channels to prevent abrasive dust ingress.","question":"How does the electrical equipment handle heavy cement dust?"}]', 'published', 1, NULL, '2026-09-16 19:48:36', '2026-09-16 19:48:36');

