INSERT INTO `testimonials` (`id`, `name`, `company`, `role`, `content`, `rating`, `avatar`, `status`, `order_index`, `created_at`, `updated_at`) VALUES (1, 'Ahmed Kabir', 'Apex Spinning & Weaving Mills', 'Director of Plant Operations', 'Solvex deployed our 1.2MW rooftop solar array with absolute precision. Our daytime diesel generator run-time dropped by 75%, and the ROI has exceeded all initial projections.', 1, 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=200', 'approved', 0, '2026-09-16 21:18:36', '2026-09-16 21:18:36');
INSERT INTO `testimonials` (`id`, `name`, `company`, `role`, `content`, `rating`, `avatar`, `status`, `order_index`, `created_at`, `updated_at`) VALUES (1, 'Dr. Marianne Weber', 'Nordic Clean Grid Infrastructure', 'Lead Environmental Engineer', 'Their utility battery energy storage system (BESS) stabilization engineering solved our intermittent offshore wind integration issues without a single day of grid curtailment.', 1, 'https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?w=200', 'approved', 1, '2026-09-16 21:18:36', '2026-09-16 21:18:36');
INSERT INTO `testimonials` (`id`, `name`, `company`, `role`, `content`, `rating`, `avatar`, `status`, `order_index`, `created_at`, `updated_at`) VALUES (1, 'Rafiqul Islam', 'Karnaphuli Energy Complex', 'Chief Technology Officer', 'Exceptional EPC engineering. From initial feasibility audits to final national grid synchronization, Solvex delivered beyond expectations with zero downtime.', 1, 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=200', 'approved', 1, '2026-09-16 21:18:36', '2026-09-16 21:18:36');
